PROGRAM ST_T06_BACKTRYCK
VAR
    tmrBlk    : TON;
    tmrStp70  : TON;
    tmrStp60  : TON;
    tmrStrt70 : TON;
    tmrStrt60 : TON;
    blockerad : BOOL := FALSE;
    hadeBlock : BOOL := FALSE;
    xOvertakt : BOOL := FALSE;
    xTill80   : BOOL := FALSE;
    xTill70   : BOOL := FALSE;
    xTill60   : BOOL := FALSE;
END_VAR

(* Linjens hogsta tillatna takt ar 36 kartonger/min (scenariot rate_hog). *)
xOvertakt := ST060_LNE_RATE > 36.0;

tmrBlk(IN := EMG_OK AND ST080_PEC_END, PT := T#2000ms);
IF tmrBlk.Q THEN
    blockerad := TRUE;
    hadeBlock := TRUE;
ELSIF NOT ST080_PEC_END THEN
    blockerad := FALSE;
END_IF;

ST080_BLK_ACT := blockerad;

tmrStp70(IN := blockerad, PT := T#800ms);
tmrStp60(IN := tmrStp70.Q, PT := T#800ms);

tmrStrt70(IN := NOT blockerad AND hadeBlock, PT := T#800ms);
tmrStrt60(IN := tmrStrt70.Q, PT := T#800ms);
IF tmrStrt60.Q THEN
    hadeBlock := FALSE;
END_IF;

IF NOT EMG_OK THEN
    xTill80 := FALSE;
    xTill70 := FALSE;
    xTill60 := FALSE;
    blockerad := FALSE;
    hadeBlock := FALSE;
ELSE
    IF blockerad THEN
        xTill80 := FALSE;
        xTill70 := NOT tmrStp70.Q;
        xTill60 := NOT tmrStp60.Q;
    ELSIF hadeBlock THEN
        xTill80 := TRUE;
        xTill70 := tmrStrt70.Q;
        xTill60 := tmrStrt60.Q;
    ELSE
        xTill80 := TRUE;
        xTill70 := TRUE;
        xTill60 := TRUE;
    END_IF;
END_IF;

ST080_CNV_RUN := xTill80;
(* En bana far inte mata fram om nedstroms star still och kartong star vid fotocellen. *)
ST070_CNV_RUN := xTill70 AND NOT (ST070_PEC_END AND NOT ST080_CNV_RUN);
(* Overtakt stryper intaget ST060 forst, liksom backtryck fran stillastaende ST070. *)
ST060_CNV_RUN := xTill60 AND NOT xOvertakt AND NOT (ST060_PEC_END AND NOT ST070_CNV_RUN);
END_PROGRAM

