PROGRAM ST_T06_BACKTRYCK
VAR
    tmrBlk    : TON;
    blockerad : BOOL := FALSE;
END_VAR

tmrBlk(IN := EMG_OK AND ST080_PEC_END, PT := T#2000ms);
IF tmrBlk.Q THEN
    blockerad := TRUE;
ELSIF NOT ST080_PEC_END THEN
    blockerad := FALSE;
END_IF;

ST080_BLK_ACT := blockerad;

IF NOT EMG_OK THEN
    ST060_CNV_RUN := FALSE;
    ST070_CNV_RUN := FALSE;
    ST080_CNV_RUN := FALSE;
ELSE
    IF blockerad THEN
        ST060_CNV_RUN := FALSE;
        ST070_CNV_RUN := TRUE;
        ST080_CNV_RUN := TRUE;
    ELSE
        ST060_CNV_RUN := TRUE;
        ST070_CNV_RUN := TRUE;
        ST080_CNV_RUN := TRUE;
    END_IF;
END_IF;
END_PROGRAM
